var abbreviateProduct = function(left, right) {
    let twos = 0;
    let fives = 0;
    let last = 1;
    let logSum = 0;
    const MOD = 100000;

    for (let i = left; i <= right; i++) {
        logSum += Math.log10(i);

        let x = i;
        while (x % 2 === 0) {
            twos++;
            x /= 2;
        }
        while (x % 5 === 0) {
            fives++;
            x /= 5;
        }

        last = (last * (x % MOD)) % MOD;
    }

    const zeros = Math.min(twos, fives);
    const extraTwos = twos - zeros;

    let base = 2;
    let exponent = extraTwos;
    while (exponent > 0) {
        if (exponent & 1) {
            last = (last * base) % MOD;
        }
        base = (base * base) % MOD;
        exponent >>= 1;
    }

    const normalizedLog = logSum - zeros;
    const digits = Math.floor(normalizedLog + 1e-9) + 1;

    if (digits <= 10) {
        let product = 1n;
        for (let i = left; i <= right; i++) {
            product *= BigInt(i);
        }

        let value = product.toString();
        while (value.endsWith("0")) {
            value = value.slice(0, -1);
        }

        return value + "e" + zeros;
    }

    const integerPart = Math.floor(normalizedLog);
    const fraction = normalizedLog - integerPart;
    const first = Math.floor(Math.pow(10, fraction + 4)).toString();
    const lastPart = Math.floor(last).toString().padStart(5, "0");

    return first + "..." + lastPart + "e" + zeros;
};
