        const incomplete = n - complete;
        const completionCost = prefix[n] - prefix[incomplete];

        if (completionCost > newFlowers) continue;

        const remainingFlowers = newFlowers - completionCost;

        if (incomplete === 0) {
            answer = Math.max(answer, complete * full);
            continue;
