        if (mask === totalMasks - 1) return 0;
        if (memo[mask] !== -1) return memo[mask];

        const operation = pairCount[mask] / 2 + 1;
        let best = 0;

        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) continue;

            for (let j = i + 1; j < m; j++) {
