var getCoprimes = function(nums, edges) {
    const n = nums.length;
    const graph = Array.from({ length: n }, () => []);

    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const coprime = Array.from({ length: 51 }, () => Array(51).fill(false));

    const gcd = (a, b) => {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
