        for (let b = 1; b <= 50; b++) {
            coprime[a][b] = gcd(a, b) === 1;
        }
    }

    const answer = Array(n).fill(-1);
    const depth = Array(n).fill(0);
    const paths = Array.from({ length: 51 }, () => []);

    const stack = [[0, -1, 0]];

    while (stack.length > 0) {
        const [node, parent, state] = stack.pop();

        if (state === 0) {
            let best = -1;
            let bestDepth = -1;

            for (let value = 1; value <= 50; value++) {
                if (coprime[nums[node]][value] && paths[value].length > 0) {
