/**
 * @param {string[]} words
 * @param {string} result
 * @return {boolean}
 */
var isSolvable = function(words, result) {
    const digitOf = new Int8Array(26);
    digitOf.fill(-1);

    const leading = new Uint8Array(26);
    const present = new Uint8Array(26);
    let uniqueCount = 0;

    const register = (word) => {
        for (let i = 0; i < word.length; i++) {
            const id = word.charCodeAt(i) - 65;
            if (!present[id]) {
                present[id] = 1;
                uniqueCount++;
            }
        }

        if (word.length > 1) {
            leading[word.charCodeAt(0) - 65] = 1;
        }
    };

    for (const word of words) register(word);
    register(result);

    if (uniqueCount > 10) return false;

    let maxLength = result.length;
    for (const word of words) {
        maxLength = Math.max(maxLength, word.length);
    }

    const columns = new Array(maxLength);

    for (let col = 0; col < maxLength; col++) {
        const counts = new Map();

        for (const word of words) {
            const pos = word.length - 1 - col;
            if (pos >= 0) {
                const id = word.charCodeAt(pos) - 65;
                counts.set(id, (counts.get(id) || 0) + 1);
            }
        }

        columns[col] = Array.from(counts.entries());
    }

    function dfsColumn(col, carry) {
        if (col === maxLength) {
            return carry === 0;
        }

        const entries = columns[col];
        const resultPos = result.length - 1 - col;
        const resultId = resultPos >= 0
            ? result.charCodeAt(resultPos) - 65
            : -1;

        function assignAddends(index, sum) {
            if (index === entries.length) {
                const total = sum + carry;
                const requiredDigit = total % 10;
                const nextCarry = Math.floor(total / 10);

                if (resultId === -1) {
                    if (requiredDigit !== 0) return false;
                    return dfsColumn(col + 1, nextCarry);
                }

                if (digitOf[resultId] !== -1) {
                    if (digitOf[resultId] !== requiredDigit) return false;
                    return dfsColumn(col + 1, nextCarry);
                }

                if (usedDigits & (1 << requiredDigit)) return false;
                if (requiredDigit === 0 && leading[resultId]) return false;

                digitOf[resultId] = requiredDigit;
                usedDigits |= 1 << requiredDigit;

                const possible = dfsColumn(col + 1, nextCarry);

                usedDigits ^= 1 << requiredDigit;
                digitOf[resultId] = -1;

                return possible;
            }

            const [id, count] = entries[index];

            if (digitOf[id] !== -1) {
                return assignAddends(
                    index + 1,
                    sum + count * digitOf[id]
                );
            }

            for (let digit = 0; digit <= 9; digit++) {
                if (usedDigits & (1 << digit)) continue;
                if (digit === 0 && leading[id]) continue;

                digitOf[id] = digit;
                usedDigits |= 1 << digit;

                if (assignAddends(index + 1, sum + count * digit)) {
                    return true;
                }

                usedDigits ^= 1 << digit;
                digitOf[id] = -1;
            }

            return false;
        }

        return assignAddends(0, 0);
    }

    let usedDigits = 0;
    return dfsColumn(0, 0);
};
